/**
 * Universal translate helper function.
 * @param {string} key - Translation key.
 * @param {string} lang - Active language code (e.g. 'en', 'hi', 'bn').
 * @param {object} params - Optional interpolation values (e.g. { name: 'Rithul', days: 15 }).
 * @returns {string} Translated string.
 */
export function translate(key, lang = 'en', params = {}) {
  const targetDict = TRANSLATIONS[lang] || TRANSLATIONS.en;
  let text = targetDict[key] ?? TRANSLATIONS.en[key] ?? key;

  if (typeof text === 'string' && params && typeof params === 'object') {
    Object.keys(params).forEach((k) => {
      text = text.replace(new RegExp(`\\{${k}\\}`, 'g'), String(params[k]));
    });
  }
  return text;
}
